"""Self-contained local operator interface assets for RAD Agent."""

# ruff: noqa: E501 - browser assets are intentionally immutable byte literals

INDEX_HTML = b"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>RAD Agent</title><link rel="stylesheet" href="/ui/app.css"></head>
<body><main>
<header><p class="eyebrow">Reasoning / Action / Decision</p><h1>RAD Agent</h1><p class="lede">Plan with a qualified model. Execute through governed tools. Review the evidence.</p></header>
<nav id="lifecycle" class="lifecycle" aria-label="Work lifecycle"><span data-state="proposed">Proposed</span><span data-state="approved">Approved</span><span data-state="executing">Executing</span><span data-state="failed">Failed</span><span data-state="verified">Verified</span></nav>
<section id="login" class="card"><h2>Operator login</h2><p>Unlock this loopback-only application with the password created during setup.</p><form id="login-form"><label>Password<input id="password" type="password" autocomplete="current-password" required minlength="12"></label><button>Unlock RAD Agent</button></form></section>
<section id="readiness" class="card hidden"><div class="split"><div><p class="eyebrow">First-run readiness</p><h2>Model connection</h2></div><span id="readiness-status" class="badge">Checking</span></div><p id="readiness-summary">Checking the authenticated model qualification registry.</p><pre id="readiness-detail" tabindex="0">No model status loaded.</pre><button id="refresh-readiness" class="secondary">Refresh model status</button><p class="note">If no qualified model is available, run <code>rad setup</code>, then <code>rad doctor</code>, and restart <code>rad serve</code>. Secrets are never displayed here.</p></section>
<section id="workspace" class="card hidden"><div class="status"><span class="dot"></span>Local operator session</div><h2>Define the work</h2><form id="goal-form"><label>Project ID<input id="project" value="my_project" pattern="[a-z][a-z0-9_-]{2,63}" required></label><label>Goal<textarea id="objective" rows="5" maxlength="8000" required placeholder="Describe the outcome, constraints, and what success means."></textarea></label><button>Generate governed plan</button></form><p class="note">Nothing is executed or published from this screen. The model can only propose a specification for your review.</p></section>
<section id="resume" class="card hidden"><h2>Resume an existing run</h2><form id="resume-form" class="row"><label>Session ID<input id="resume-id" autocomplete="off" required></label><button>Resume from checkpoint</button></form></section>
<section id="review" class="card hidden"><div class="status amber">Human review required</div><h2>Editable candidate plan</h2><pre id="candidate" tabindex="0"></pre><p id="digest" class="mono"></p><label>Revision instructions<textarea id="revision-instructions" rows="4" maxlength="8000" placeholder="Describe exact changes to constraints, acceptance criteria, risk handling, or scope."></textarea></label><div class="row"><button id="revise" class="secondary">Generate revised plan</button><button id="approve">Approve exact specification</button></div><p class="note">Editing creates a new immutable model-generated revision and digest. It never changes or approves the displayed candidate in place.</p></section>
<section id="runtime-setup" class="card hidden"><div class="status">Approved boundary</div><h2>Start governed runtime</h2><p>The runtime may write only deterministic JSON artifacts below <code>.rad-agent-artifacts</code> in this approved workspace.</p><form id="runtime-form"><label>Workspace root<input id="workspace-root" required placeholder="/absolute/path/to/existing/workspace"></label><button>Initialize runtime</button></form></section>
<section id="task-proposal" class="card hidden"><div class="status amber">Proposed task content</div><h2>Qualified task artifact</h2><p>Review the model-proposed content and its exact digest before governed execution.</p><pre id="task-artifact" tabindex="0"></pre><p id="task-artifact-digest" class="mono"></p></section>
<section id="runtime" class="card hidden"><div class="split"><div><p class="eyebrow">Execution timeline</p><h2 id="run-state">Not started</h2></div><button id="refresh" class="secondary">Refresh checkpoint</button></div><p id="session-label" class="mono"></p><progress id="run-progress" value="0" max="1"></progress><p id="progress-label" class="note">0 of 0 tasks complete</p><div id="tasks" class="tasks" aria-label="Task execution timeline"></div><h3>Exact next tool call</h3><pre id="preview" tabindex="0">No ready action.</pre><div class="run-controls"><button id="tick" disabled>Run one governed step</button><label>Maximum automatic steps<input id="step-limit" type="number" min="1" max="100" value="25"></label><label class="check"><input id="auto-verify" type="checkbox" checked>Verify automatically after success</label><button id="auto-run" disabled>Run safe steps automatically</button><button id="pause-run" class="secondary" disabled>Pause after current step</button><button id="resume-run" class="secondary" disabled>Resume execution</button><button id="cancel-run" class="danger" disabled>Cancel run</button><button id="verify" class="secondary hidden">Verify completion</button></div><p class="note">Pause is durable and occurs only between governed steps. Cancel is terminal, cancels every unfinished task, and requires a second confirmation click.</p></section>
<section id="approval" class="card hidden"><div class="status amber">Consequential action paused</div><h2>Approval decision</h2><p>Compare the effect and action digest with the exact preview. Approval is single-use and bound to this run.</p><pre id="approval-detail"></pre><label>Decision reason (optional)<textarea id="approval-reason" rows="2" maxlength="2000"></textarea></label><div class="row"><button id="allow">Approve exact action</button><button id="deny" class="danger">Deny action</button></div></section>
<section id="evidence" class="card hidden"><div class="split"><div><p class="eyebrow">Evidence</p><h2>Verifiable record</h2></div><div><span id="chain-status" class="badge">EMPTY</span><span id="evidence-count" class="badge">0 records</span></div></div><p>Each successful task and acceptance result is digest-bound in an append-only local chain.</p><p id="chain-head" class="mono">No evidence head yet.</p><pre id="evidence-list" tabindex="0">No evidence recorded yet.</pre></section>
<section id="downloads" class="card hidden"><div class="split"><div><p class="eyebrow">Downloads</p><h2>Verified results package</h2></div><span id="artifact-count" class="badge">0 artifacts</span></div><p>Download governed workspace artifacts, the complete evidence chain, or the verification report. Artifact bytes are revalidated against the immutable task graph before delivery.</p><div id="artifact-list" class="tasks"><p class="note">No completed artifacts are available yet.</p></div><div class="row"><button id="download-evidence" class="secondary" disabled>Download evidence JSON</button><button id="download-report" class="secondary" disabled>Download verification report</button></div></section>
<section id="completion" class="card hidden"><div id="completion-status" class="status">Completion status</div><h2 id="completion-title">Completion report</h2><p id="completion-summary">This report distinguishes local evidence verification from production qualification.</p><pre id="completion-report" tabindex="0"></pre></section>
<div id="message" role="status" aria-live="polite"></div>
</main><script src="/ui/app.js" defer></script></body></html>"""

APP_CSS = b""":root{color-scheme:dark;--bg:#07111f;--card:#0e1b2d;--line:#29415f;--text:#ecf4ff;--muted:#a9bad0;--accent:#59d7c5;--amber:#ffc66d;--danger:#ff8c8c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#173252,var(--bg) 42%);color:var(--text);font:16px/1.55 system-ui,sans-serif;min-height:100vh}main{width:min(900px,92%);margin:auto;padding:56px 0 90px}header{margin-bottom:30px}h1{font-size:clamp(2.7rem,8vw,5.2rem);margin:0;letter-spacing:-.06em}h2{margin:.15rem 0 .65rem}h3{margin-top:1.6rem}.lede{font-size:1.15rem;color:var(--muted);max-width:650px}.eyebrow{color:var(--accent);font-weight:800;letter-spacing:.14em;text-transform:uppercase;font-size:.78rem}.card{background:rgba(14,27,45,.96);border:1px solid var(--line);border-radius:20px;padding:28px;margin:18px 0;box-shadow:0 20px 60px #0005}.hidden{display:none!important}label{display:block;color:var(--muted);margin:14px 0}input,textarea{display:block;width:100%;margin-top:7px;padding:13px;border:1px solid #426181;border-radius:10px;background:#07111f;color:var(--text);font:inherit}button{border:0;border-radius:10px;padding:13px 18px;background:var(--accent);color:#06201c;font-weight:800;cursor:pointer;margin:4px 8px 4px 0}button:disabled{cursor:not-allowed;opacity:.45}.secondary{background:#29415f;color:var(--text)}.danger{background:var(--danger);color:#2b0808}button:focus,input:focus,textarea:focus,pre:focus{outline:3px solid #fff;outline-offset:3px}.status{color:var(--accent);font-weight:800;margin-bottom:16px}.amber{color:var(--amber)}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--accent);margin-right:8px}pre{white-space:pre-wrap;overflow:auto;background:#07111f;padding:18px;border-radius:12px;border:1px solid var(--line);max-height:55vh;font:13px/1.55 ui-monospace,monospace}.note,#message{color:var(--muted)}#message{position:sticky;bottom:15px;background:#07111fee;border:1px solid var(--line);border-radius:12px;padding:12px 16px;min-height:49px}.mono{font:12px ui-monospace,monospace;overflow-wrap:anywhere}.row,.split{display:flex;gap:12px;align-items:end}.row label{flex:1}.split{align-items:center;justify-content:space-between}.run-controls{display:flex;flex-wrap:wrap;align-items:end;gap:8px}.run-controls label{width:190px;margin:0}.run-controls input{padding:10px}.run-controls .check{display:flex;align-items:center;gap:8px;width:240px;color:var(--text)}.run-controls .check input{width:auto;margin:0}.tasks{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}.task{border:1px solid var(--line);border-radius:10px;padding:10px 12px}.task strong{display:block;overflow-wrap:anywhere}.task span,.badge{color:var(--muted);font-size:.82rem}.badge{border:1px solid var(--line);border-radius:999px;padding:6px 10px;margin-left:6px}progress{width:100%;height:12px;accent-color:var(--accent)}@media(max-width:620px){.row,.split,.run-controls{align-items:stretch;flex-direction:column}.row button,.run-controls button,.run-controls label{width:100%}}"""

APP_CSS += b""".lifecycle{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:18px 0}.lifecycle span{border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:.78rem;font-weight:800;padding:8px;text-align:center;text-transform:uppercase}.lifecycle span.active{background:var(--accent);border-color:var(--accent);color:#06201c}.lifecycle span.active[data-state="failed"]{background:var(--danger);border-color:var(--danger);color:#2b0808}.lifecycle span.active[data-state="proposed"]{background:var(--amber);border-color:var(--amber);color:#2b1b00}@media(max-width:620px){.lifecycle{grid-template-columns:1fr 1fr}}"""

APP_JS = b"""'use strict';
const q=(s)=>document.querySelector(s),msg=q('#message');let token='',session='',digest='',approval=null,previewReady=false,autoRunning=false,stopRequested=false,runState='',cancelArmed=false,lastEvidence=null,lastReport=null;
const key=(name)=>crypto.randomUUID()+'-'+name;
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const response=await fetch(path,{...options,headers,cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.message||'Request failed safely');return body}
function show(id){q(id).classList.remove('hidden')}
function setLifecycle(state){document.querySelectorAll('#lifecycle span').forEach((item)=>item.classList.toggle('active',item.dataset.state===state))}
async function loadReadiness(){show('#readiness');q('#readiness-status').textContent='Checking';try{const models=await api('/v1/model-qualifications');const ready=models.length>0;q('#readiness-status').textContent=ready?'Qualified':'Setup required';q('#readiness-summary').textContent=ready?`${models.length} active model qualification${models.length===1?'':'s'} available.`:'No active model qualification is registered for this server.';q('#readiness-detail').textContent=ready?JSON.stringify(models,null,2):'Run rad setup, then rad doctor, and restart rad serve.';return ready}catch(error){q('#readiness-status').textContent='Unavailable';q('#readiness-summary').textContent='Model readiness could not be checked safely.';q('#readiness-detail').textContent=error.message;return false}}
function renderRuntime(body){show('#runtime');show('#evidence');runState=body.run_state;setLifecycle(body.run_state==='FAILED'||body.run_state==='CANCELLED'?'failed':'executing');q('#run-state').textContent=body.run_state;q('#session-label').textContent=`Session ${session} / Run ${body.run_id}`;const states=Object.values(body.task_states),done=states.filter((state)=>state==='SUCCEEDED').length;q('#run-progress').max=Math.max(states.length,1);q('#run-progress').value=done;q('#progress-label').textContent=`${done} of ${states.length} tasks complete`;q('#tasks').replaceChildren(...Object.entries(body.task_states).map(([id,state])=>{const item=document.createElement('div');item.className='task';const strong=document.createElement('strong');strong.textContent=id;const span=document.createElement('span');span.textContent=state;item.append(strong,span);return item}));q('#verify').classList.toggle('hidden',body.run_state!=='SUCCEEDED');setRunControls()}
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();URL.revokeObjectURL(url)}
function downloadJson(name,value){download(name,JSON.stringify(value,null,2)+'\n')}
async function loadArtifacts(){const body=await api(`/v1/agent/sessions/${session}/runtime/artifacts`);show('#downloads');q('#artifact-count').textContent=`${body.artifacts.length} artifact${body.artifacts.length===1?'':'s'}`;if(!body.artifacts.length){q('#artifact-list').replaceChildren(Object.assign(document.createElement('p'),{className:'note',textContent:'No completed artifacts are available yet.'}));return body}q('#artifact-list').replaceChildren(...body.artifacts.map((artifact)=>{const item=document.createElement('div');item.className='task';const strong=document.createElement('strong');strong.textContent=artifact.name;const detail=document.createElement('span');detail.textContent=`${artifact.bytes} bytes / ${artifact.sha256}`;const button=document.createElement('button');button.className='secondary';button.textContent='Download artifact';button.addEventListener('click',async()=>{try{const file=await api(`/v1/agent/sessions/${session}/runtime/artifacts/${artifact.task_id}`);const binary=atob(file.content_base64),bytes=Uint8Array.from(binary,(character)=>character.charCodeAt(0));download(file.name,bytes,file.media_type);msg.textContent=`Downloaded verified artifact ${file.name}.`}catch(error){msg.textContent=error.message}});item.append(strong,detail,button);return item}));return body}
async function loadEvidence(){try{const body=await api(`/v1/agent/sessions/${session}/runtime/evidence`);lastEvidence=body;q('#download-evidence').disabled=false;show('#downloads');q('#evidence-count').textContent=`${body.record_count} records`;q('#chain-status').textContent=body.chain_status;q('#chain-head').textContent=body.head_hash?`Verified head: ${body.head_hash}`:'No evidence head yet.';q('#evidence-list').textContent=body.records.length?JSON.stringify(body.records,null,2):'No evidence recorded yet.';return body}catch(error){lastEvidence=null;q('#download-evidence').disabled=true;q('#chain-status').textContent='INVALID';q('#chain-head').textContent='Evidence integrity could not be verified.';q('#evidence-list').textContent=error.message;q('#completion').classList.add('hidden');throw error}}
function showCompletion(passed,sessionBody,evidenceBody){const successful=passed&&sessionBody.state==='COMPLETED'&&evidenceBody.chain_status==='VERIFIED';setLifecycle(successful?'verified':sessionBody.state==='FAILED'?'failed':'executing');const acceptanceRecords=evidenceBody.records.filter((record)=>record.kind==='TEST'),passingAcceptance=acceptanceRecords.filter((record)=>record.outcome==='PASS').length;const report={schema_version:'1.0',session_id:session,run_id:evidenceBody.run_id,session_state:sessionBody.state,verification_passed:passed,evidence_chain:evidenceBody.chain_status,evidence_records:evidenceBody.record_count,evidence_head:evidenceBody.head_hash,acceptance_summary:{passed:passingAcceptance,total:acceptanceRecords.length}};if(successful){report.qualification_state='LOCAL_VERIFIED_NOT_PRODUCTION';report.limitations=['No shell, network, publishing, deployment, deletion, or production authorization.']}lastReport=report;q('#download-report').disabled=false;q('#completion-status').textContent=successful?'Verification complete':sessionBody.state==='FAILED'?'Run failed':'Verification failed';q('#completion-status').classList.toggle('amber',!successful);q('#completion-title').textContent=successful?'Verified completion report':sessionBody.state==='FAILED'?'Failed run report':'Unverified completion report';q('#completion-summary').textContent=successful?`${passingAcceptance} of ${acceptanceRecords.length} acceptance checks passed with a verified evidence chain. This is not production qualification.`:sessionBody.state==='FAILED'?'The run failed. Valid evidence remains inspectable, but no success qualification is granted.':'Acceptance verification did not pass. No success qualification is granted.';q('#completion-report').textContent=JSON.stringify(report,null,2);show('#completion');show('#downloads');q('#verify').classList.toggle('hidden',sessionBody.state!=='COMPLETED')}
async function verifyCompletion(){msg.textContent='Verifying evidence-bound acceptance criteria...';const body=await api(`/v1/agent/sessions/${session}/runtime/verify`,{method:'POST',headers:{'Idempotency-Key':key('verify')}});const evidenceBody=await loadEvidence();showCompletion(body.passed,body.session,evidenceBody);await loadArtifacts().catch(()=>null);msg.textContent=body.passed?'Verification passed. The local session is complete and results are ready to download.':'Verification failed. The session is not complete.';return body.passed}
function setRunControls(){const terminal=['SUCCEEDED','FAILED','CANCELLED'].includes(runState);q('#tick').disabled=!previewReady||autoRunning||runState==='PAUSED';q('#auto-run').disabled=!previewReady||autoRunning||runState==='PAUSED';q('#pause-run').disabled=runState!=='RUNNING'||stopRequested;q('#resume-run').disabled=runState!=='PAUSED'||autoRunning;q('#cancel-run').disabled=!runState||terminal||autoRunning;q('#step-limit').disabled=autoRunning}
async function loadPreview(){previewReady=false;setRunControls();try{const proposed=await api(`/v1/agent/sessions/${session}/runtime/preparations`,{method:'POST',headers:{'Idempotency-Key':key('prepare')}});q('#task-artifact').textContent=JSON.stringify(proposed.artifact,null,2);q('#task-artifact-digest').textContent=`Digest: ${proposed.artifact_digest}`;show('#task-proposal');const body=await api(`/v1/agent/sessions/${session}/runtime/preview`);q('#preview').textContent=JSON.stringify(body,null,2);previewReady=body.decision!=='DENY';setRunControls();msg.textContent=body.approval_required?'Review the exact proposal and action; execution will pause for approval.':'Qualified proposal and exact governed action are ready for review.';return previewReady}catch(error){q('#preview').textContent='No ready action.';msg.textContent=error.message;return false}}
async function refreshRuntime(){const body=await api(`/v1/agent/sessions/${session}/runtime`);renderRuntime(body);const evidenceBody=await loadEvidence();const sessionBody=await api(`/v1/agent/sessions/${session}`);if(sessionBody.state==='COMPLETED'||sessionBody.state==='FAILED'){showCompletion(sessionBody.state==='COMPLETED',sessionBody,evidenceBody);await loadArtifacts().catch(()=>null)}if(body.run_state==='READY'||body.run_state==='RUNNING')await loadPreview();else{previewReady=false;setRunControls()}}
q('#login-form').addEventListener('submit',async(e)=>{e.preventDefault();msg.textContent='Authenticating...';try{const body=await api('/v1/auth/login',{method:'POST',body:JSON.stringify({password:q('#password').value})});token=body.access_token;q('#password').value='';q('#login').classList.add('hidden');show('#workspace');show('#resume');await loadReadiness();msg.textContent='Authenticated locally. Review model readiness, create new work, or resume a durable session.'}catch(error){msg.textContent=error.message}});
q('#refresh-readiness').addEventListener('click',async()=>{await loadReadiness();msg.textContent='Model readiness refreshed.'});
q('#goal-form').addEventListener('submit',async(e)=>{e.preventDefault();msg.textContent='Generating and validating the candidate...';try{const body=await api('/v1/agent/sessions',{method:'POST',headers:{'Idempotency-Key':key('create')},body:JSON.stringify({project_id:q('#project').value,objective:q('#objective').value})});session=body.session_id;q('#resume-id').value=session;const candidate=await api(`/v1/agent/sessions/${session}/candidate`);digest=candidate.candidate_digest;q('#candidate').textContent=JSON.stringify(candidate,null,2);q('#digest').textContent=`Digest: ${digest}`;show('#review');setLifecycle('proposed');msg.textContent='Review every field before approval.'}catch(error){msg.textContent=error.message}});
q('#revise').addEventListener('click',async()=>{const instructions=q('#revision-instructions').value.trim();if(!instructions){msg.textContent='Enter revision instructions before generating a new plan.';return}q('#revise').disabled=true;q('#approve').disabled=true;msg.textContent='Generating and validating an immutable candidate revision...';try{const candidate=await api(`/v1/agent/sessions/${session}/candidate/revisions`,{method:'POST',headers:{'Idempotency-Key':key('revise')},body:JSON.stringify({instructions})});digest=candidate.candidate_digest;q('#candidate').textContent=JSON.stringify(candidate,null,2);q('#digest').textContent=`Revision ${candidate.revision} digest: ${digest}`;q('#revision-instructions').value='';q('#approve').disabled=false;setLifecycle('proposed');msg.textContent='Revised plan ready. Review the new revision and digest before approval.'}catch(error){q('#approve').disabled=false;msg.textContent=error.message}finally{q('#revise').disabled=false}});
q('#approve').addEventListener('click',async()=>{msg.textContent='Recording exact-digest approval...';try{const body=await api(`/v1/agent/sessions/${session}/approve`,{method:'POST',headers:{'Idempotency-Key':key('approve')},body:JSON.stringify({candidate_digest:digest})});q('#approve').disabled=true;show('#runtime-setup');setLifecycle('approved');msg.textContent=`Approved. Session state: ${body.state}. Choose the bounded workspace before execution.`}catch(error){msg.textContent=error.message}});
q('#runtime-form').addEventListener('submit',async(e)=>{e.preventDefault();msg.textContent='Initializing durable runtime...';try{const body=await api(`/v1/agent/sessions/${session}/runtime`,{method:'POST',headers:{'Idempotency-Key':key('start')},body:JSON.stringify({workspace_root:q('#workspace-root').value})});renderRuntime(body);await loadEvidence();await loadPreview()}catch(error){msg.textContent=error.message}});
q('#resume-form').addEventListener('submit',async(e)=>{e.preventDefault();session=q('#resume-id').value.trim();msg.textContent='Recovering durable checkpoint...';try{await refreshRuntime();msg.textContent='Runtime recovered from its durable checkpoint.'}catch(error){msg.textContent=error.message}});
q('#refresh').addEventListener('click',async()=>{try{await refreshRuntime();msg.textContent='Checkpoint, preview, and evidence refreshed.'}catch(error){msg.textContent=error.message}});
async function executeStep(){if(!previewReady)return null;previewReady=false;setRunControls();const body=await api(`/v1/agent/sessions/${session}/runtime/ticks`,{method:'POST',headers:{'Idempotency-Key':key('tick')},body:JSON.stringify({})});renderRuntime(body.runtime);if(body.outcome==='APPROVAL_REQUIRED'){approval=body.approval;q('#approval-detail').textContent=JSON.stringify(approval,null,2);show('#approval');msg.textContent='Execution paused. Human approval is required.'}else{await loadEvidence();if(body.runtime.run_state!=='SUCCEEDED')await loadPreview()}return body}
q('#tick').addEventListener('click',async()=>{msg.textContent='Advancing exactly one governed task...';try{const body=await executeStep();if(body&&body.runtime.run_state==='SUCCEEDED'&&q('#auto-verify').checked)await verifyCompletion();else if(body)msg.textContent=`Governed step outcome: ${body.outcome}.`}catch(error){msg.textContent=error.message;await refreshRuntime()}});
async function pauseExecution(){const body=await api(`/v1/agent/sessions/${session}/runtime/pause`,{method:'POST',headers:{'Idempotency-Key':key('pause')}});previewReady=false;renderRuntime(body);msg.textContent='Runtime paused durably between governed steps.';return body}
q('#auto-run').addEventListener('click',async()=>{if(autoRunning||!previewReady)return;const limit=Number.parseInt(q('#step-limit').value,10);if(!Number.isInteger(limit)||limit<1||limit>100){msg.textContent='Automatic step limit must be from 1 to 100.';return}autoRunning=true;stopRequested=false;setRunControls();let completed=0,last=null;msg.textContent=`Automatic mode started with a ${limit}-step limit.`;try{while(!stopRequested&&completed<limit&&previewReady){last=await executeStep();if(!last)break;completed+=1;if(last.outcome!=='SUCCEEDED'||last.runtime.run_state==='SUCCEEDED')break;await new Promise((resolve)=>setTimeout(resolve,0))}if(last&&last.runtime.run_state==='SUCCEEDED'&&q('#auto-verify').checked){await verifyCompletion();return}if(stopRequested&&runState==='RUNNING'){await pauseExecution();msg.textContent=`Paused durably after ${completed} completed step(s).`}else if(completed===limit)msg.textContent=`Paused at the configured ${limit}-step limit.`;else if(approval)msg.textContent='Automatic mode paused for human approval.';else msg.textContent=`Automatic mode paused after ${completed} completed step(s).`}catch(error){msg.textContent=error.message;await refreshRuntime()}finally{autoRunning=false;stopRequested=false;setRunControls()}});
q('#pause-run').addEventListener('click',async()=>{if(autoRunning){stopRequested=true;setRunControls();msg.textContent='Pause requested. The current governed step will finish; no next step will start.';return}try{await pauseExecution()}catch(error){msg.textContent=error.message;await refreshRuntime()}});
q('#resume-run').addEventListener('click',async()=>{try{const body=await api(`/v1/agent/sessions/${session}/runtime/resume`,{method:'POST',headers:{'Idempotency-Key':key('resume')}});renderRuntime(body);await loadPreview();msg.textContent='Durable runtime checkpoint resumed.'}catch(error){msg.textContent=error.message;await refreshRuntime()}});
q('#cancel-run').addEventListener('click',async()=>{if(!cancelArmed){cancelArmed=true;q('#cancel-run').textContent='Confirm cancel run';msg.textContent='Cancellation is terminal. Click Confirm cancel run to continue.';return}try{const body=await api(`/v1/agent/sessions/${session}/runtime/cancel`,{method:'POST',headers:{'Idempotency-Key':key('cancel')}});previewReady=false;renderRuntime(body.runtime);q('#preview').textContent='Run cancelled. No further action is executable.';q('#cancel-run').textContent='Cancel run';cancelArmed=false;msg.textContent='Runtime and Agent session cancelled durably.'}catch(error){cancelArmed=false;q('#cancel-run').textContent='Cancel run';msg.textContent=error.message;await refreshRuntime()}});
async function decide(status){if(!approval)return;try{const reason=q('#approval-reason').value;const decision=reason?{status,reason}:{status};await api(`/v1/agent/sessions/${session}/runtime/approvals/${approval.approval_id}`,{method:'POST',headers:{'Idempotency-Key':key(status.toLowerCase())},body:JSON.stringify(decision)});q('#approval').classList.add('hidden');if(status==='APPROVED'){const body=await api(`/v1/agent/sessions/${session}/runtime/ticks`,{method:'POST',headers:{'Idempotency-Key':key('approved-tick')},body:JSON.stringify({approval_id:approval.approval_id})});renderRuntime(body.runtime);await loadEvidence();if(body.runtime.run_state==='SUCCEEDED'&&q('#auto-verify').checked)await verifyCompletion();else if(body.runtime.run_state!=='SUCCEEDED')await loadPreview();if(body.runtime.run_state!=='SUCCEEDED'||!q('#auto-verify').checked)msg.textContent=`Approved action outcome: ${body.outcome}.`}else{msg.textContent='Action denied. Runtime remains paused for operator review.'}approval=null}catch(error){msg.textContent=error.message}}
q('#allow').addEventListener('click',()=>decide('APPROVED'));q('#deny').addEventListener('click',()=>decide('DENIED'));
q('#download-evidence').addEventListener('click',()=>{if(lastEvidence)downloadJson(`rad-evidence-${session}.json`,lastEvidence)});q('#download-report').addEventListener('click',()=>{if(lastReport)downloadJson(`rad-verification-${session}.json`,lastReport)});
q('#verify').addEventListener('click',async()=>{try{await verifyCompletion()}catch(error){msg.textContent=error.message}});"""
